import os
from datetime import datetime, timezone
from typing import Dict, List, Optional, Sequence, Tuple, Union

import boto3


DimensionInput = Union[Dict[str, str], Sequence[Tuple[str, str]]]


def _to_dimensions(dimensions: Optional[DimensionInput]) -> List[Dict[str, str]]:
    if not dimensions:
        return []
    if isinstance(dimensions, dict):
        return [{"Name": k, "Value": v} for k, v in sorted(dimensions.items())]
    return [{"Name": k, "Value": v} for k, v in dimensions]


def _ensure_utc(dt: datetime) -> datetime:
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def compare_cloudwatch_metric_values(
    namespace: str,
    metric_name: str,
    start_time: datetime,
    end_time: datetime,
    period: int,
    stat: str,
    resource_a_dimensions: Optional[DimensionInput] = None,
    resource_b_dimensions: Optional[DimensionInput] = None,
    unit: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, object]:
    start_time = _ensure_utc(start_time)
    end_time = _ensure_utc(end_time)

    client = boto3.client(
        "cloudwatch",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
    )

    metric_stat_base = {
        "Namespace": namespace,
        "MetricName": metric_name,
    }
    if unit:
        metric_stat_base["Unit"] = unit

    queries = [
        {
            "Id": "a",
            "Label": "resource_a",
            "ReturnData": True,
            "MetricStat": {
                "Metric": {
                    **metric_stat_base,
                    "Dimensions": _to_dimensions(resource_a_dimensions),
                },
                "Period": period,
                "Stat": stat,
            },
        },
        {
            "Id": "b",
            "Label": "resource_b",
            "ReturnData": True,
            "MetricStat": {
                "Metric": {
                    **metric_stat_base,
                    "Dimensions": _to_dimensions(resource_b_dimensions),
                },
                "Period": period,
                "Stat": stat,
            },
        },
    ]

    response = client.get_metric_data(
        MetricDataQueries=queries,
        StartTime=start_time,
        EndTime=end_time,
        ScanBy="TimestampAscending",
    )

    results = {item["Id"]: item for item in response.get("MetricDataResults", [])}

    a_result = results.get("a", {})
    b_result = results.get("b", {})

    a_values = a_result.get("Values", [])
    b_values = b_result.get("Values", [])
    a_timestamps = a_result.get("Timestamps", [])
    b_timestamps = b_result.get("Timestamps", [])

    a_latest = a_values[-1] if a_values else None
    b_latest = b_values[-1] if b_values else None

    difference = None
    percent_difference = None

    if a_latest is not None and b_latest is not None:
        difference = a_latest - b_latest
        if b_latest != 0:
            percent_difference = (difference / b_latest) * 100.0

    return {
        "provider": "aws_cloudwatch",
        "namespace": namespace,
        "metric_name": metric_name,
        "stat": stat,
        "period": period,
        "start_time": start_time.isoformat(),
        "end_time": end_time.isoformat(),
        "resource_a": {
            "dimensions": _to_dimensions(resource_a_dimensions),
            "timestamps": [ts.isoformat() for ts in a_timestamps],
            "values": a_values,
            "latest_value": a_latest,
            "status_code": a_result.get("StatusCode"),
            "messages": a_result.get("Messages", []),
        },
        "resource_b": {
            "dimensions": _to_dimensions(resource_b_dimensions),
            "timestamps": [ts.isoformat() for ts in b_timestamps],
            "values": b_values,
            "latest_value": b_latest,
            "status_code": b_result.get("StatusCode"),
            "messages": b_result.get("Messages", []),
        },
        "comparison": {
            "difference": difference,
            "percent_difference_vs_b": percent_difference,
            "window_point_count_a": len(a_values),
            "window_point_count_b": len(b_values),
        },
        "next_token": response.get("NextToken"),
    }
